import AppKit

/// The menu bar icon artwork: template PDFs drawn from the website's logo geometry
/// (Resources/MenuBarIcons, generated by scripts/make-menubar-icons.swift). Shipped inside the
/// app bundle at Contents/Resources/MenuBarIcons; when the app runs straight from `swift build`
/// (no bundle) it falls back to SF Symbols so development still works.
@MainActor
enum MenuBarIcon {
    enum State: Equatable {
        case signedOut, idle, dropTarget
        case busy(frame: Int)
    }

    /// The busy loop: `busy-01` ... `busy-12` at 12 fps (Resources/MenuBarIcons/README.md).
    static let busyFrameCount = 12
    static let busyFrameInterval: TimeInterval = 1.0 / 12.0

    private static var cache: [String: NSImage] = [:]

    static func image(for state: State) -> NSImage? {
        let name: String
        switch state {
        case .signedOut: name = "signedOut"
        case .idle: name = "idle"
        case .dropTarget: name = "dropTarget"
        case .busy(let frame): name = String(format: "busy-%02d", (frame % busyFrameCount) + 1)
        }
        if let image = bundled(name) { return image }
        return fallback(for: state)
    }

    private static func bundled(_ name: String) -> NSImage? {
        if let cached = cache[name] { return cached }
        guard let url = Bundle.main.url(forResource: "MenuBarIcon-\(name)", withExtension: "pdf", subdirectory: "MenuBarIcons"),
              let image = NSImage(contentsOf: url)
        else { return nil }
        image.isTemplate = true
        image.size = NSSize(width: 20, height: 20)
        image.accessibilityDescription = "Upload the File"
        cache[name] = image
        return image
    }

    private static func fallback(for state: State) -> NSImage? {
        let symbol: String
        switch state {
        case .signedOut: symbol = "arrow.up.doc"
        case .idle: symbol = "arrow.up.doc"
        case .dropTarget, .busy: symbol = "arrow.up.doc.fill"
        }
        let image = NSImage(systemSymbolName: symbol, accessibilityDescription: "Upload the File")
        image?.isTemplate = true
        return image
    }
}
